import { StatusView } from '../../../shared/models/status-tone.model';

export type EmployeeStatus = 'active' | 'leave' | 'terminated';

/** Staff member card, linked to a department (cost center) and an advances account. */
export interface Employee {
  id: string;
  /** `EMP-0012`, generated by the server. */
  code: string;
  name: string;
  jobTitle: string;
  /** Department = cost center. */
  costCenterId: string | null;
  costCenterName: string | null;
  costCenterColor: string | null;
  phone: string;
  nationalId: string;
  /** ISO date. */
  hireDate: string;
  /** Monthly gross salary (EGP). */
  salary: number;
  /** Leaf account that tracks this employee's advances (سلف). */
  advancesAccountId: string | null;
  advancesAccountName: string | null;
  status: EmployeeStatus;
  notes: string;
  createdAt: string;
}

export type EmployeePayload = Pick<
  Employee,
  'name' | 'jobTitle' | 'costCenterId' | 'phone' | 'nationalId' | 'hireDate' | 'salary' | 'advancesAccountId' | 'status' | 'notes'
>;

export interface EmployeeDepartmentStat {
  costCenterId: string | null;
  name: string;
  color: string;
  count: number;
  salaries: number;
}

/** `GET employees/stats` — over the same search / filters as the list (status ignored). */
export interface EmployeeStats {
  headcount: number;
  active: number;
  onLeave: number;
  /** Monthly salaries of active + on-leave staff. */
  totalSalaries: number;
  averageSalary: number;
  byDepartment: EmployeeDepartmentStat[];
}

export const EMPLOYEE_STATUSES: readonly EmployeeStatus[] = ['active', 'leave', 'terminated'];

export const EMPLOYEE_STATUS_VIEW: Record<EmployeeStatus, StatusView> = {
  active: { label: 'على رأس العمل', tone: 'good', color: 'var(--gr)' },
  leave: { label: 'في إجازة', tone: 'warning', color: 'var(--am)' },
  terminated: { label: 'انتهت خدمته', tone: 'neutral', color: 'var(--txt3)' },
};

export const EMPLOYEES_PLURAL = { one: 'موظف واحد', two: 'موظفان', few: '# موظفين', other: '# موظف' };
